import assert from "node:assert/strict";
import { test } from "node:test";
import { truncate } from "../src/index.js";

test("returns text unchanged when within max", () => {
  assert.equal(truncate("abc", 3), "abc");
  assert.equal(truncate("abc", 10), "abc");
});

test("truncates with a single ellipsis character at exactly max length", () => {
  assert.equal(truncate("abcdef", 4), "abc…");
  assert.equal(truncate("abcdef", 4).length, 4);
  assert.equal(truncate("abcdef", 1), "…");
});
